function englishSpellDescription(spell) {
  const type = spell?.type || "utility";
  const dmg = spell?.dmg && spell.dmg !== "0" ? ` Power: ${spell.dmg}.` : "";
  if(type === "heal") return `Restorative magic that heals allies and turns the battle back in your favor.${dmg}`;
  if(type === "damage") return `Offensive magic that strikes the enemy with focused force.${dmg}`;
  if(type === "control") return `Control magic that disrupts enemy actions, timing, or positioning.${dmg}`;
  if(type === "defense") return `Protective magic that raises defenses or prevents incoming harm.${dmg}`;
  if(type === "buff") return `Empowering magic that strengthens you or the whole party.${dmg}`;
  if(type === "summon") return `Summoning magic that calls an ally or manifestation onto the battlefield.${dmg}`;
  return `Utility magic that changes the flow of the encounter.${dmg}`;
}

function spellDisplay(spell, lang = "it") {
  if(lang !== "en" || !spell) return spell;
  return {
    ...spell,
    name: spell.name_en || SPELL_NAME_EN[spell.name] || spell.name,
    desc: spell.desc_en || englishSpellDescription(spell),
  };
}

function availableSpellsFor(className, level, vault=null) {
  if(className === 'custode_equilibrio') {
    const zodarBase = (SPELLS.custode_equilibrio?.[0] || []).map(s => ({ ...s, slot: 0 }));
    const unlockedCardSpells = Object.values(CARD_UNLOCK_SPELLS)
      .filter(spell => unlockedSpellCardIdsFromVault(vault).has(spell.cardId) && spell.compatibleClasses.includes(className))
      .map(spell => ({ ...spell, slot:Number(spell.slots || 0), fromCard:true }));
    return [...zodarBase, ...unlockedCardSpells];
  }
  const packs = SPELLS[className] || {};
  const slotsForLevel = getSpellSlots(level);
  const maxSlot = Math.max(...Object.entries(slotsForLevel).filter(([,v])=>v>0).map(([k])=>Number(k)), 1);
  const baseSpells = Object.entries(packs)
    .filter(([slot]) => Number(slot) <= maxSlot)
    .flatMap(([slot, spells]) => spells.map(s => ({ ...s, slot: Number(slot) })));
  const unlockedCardSpells = Object.values(CARD_UNLOCK_SPELLS)
    .filter(spell => unlockedSpellCardIdsFromVault(vault).has(spell.cardId))
    .filter(spell => spell.compatibleClasses.includes(className))
    .filter(spell => Number(spell.slots || 0) <= maxSlot)
    .map(spell => ({ ...spell, slot:Number(spell.slots || 0), fromCard:true }));
  const existingIds = new Set(baseSpells.map(spell => spell.id));
  return [...baseSpells, ...unlockedCardSpells.filter(spell => !existingIds.has(spell.id))];
}

function totalSlots(slots) {
  if(!slots) return 0;
  return Object.values(slots).reduce((sum,v)=>sum + (Number(v)||0), 0);
}

function formatSpellSlots(slots) {
  if(!slots) return "0";
  return Object.entries(slots).map(([lvl,count])=>`${lvl}:${count}`).join(" ");
}
function maxPreparedSpellsForLevel(level) {
  if(level <= 1) return 2;
  if(level === 2) return 3;
  if(level === 3) return 4;
  if(level === 4) return 5;
  return Math.min(10, level + 1);
}

/* ----------------------------------------------
   DAILY QUEST ROTATION
---------------------------------------------- */
function _dateToSeed(dateStr) {
  let h = 2166136261;
  for (const c of dateStr) { h = Math.imul(h ^ c.charCodeAt(0), 16777619) >>> 0; }
  return h;
}
function _makeRng(seed) {
  let s = (seed || 1) >>> 0;
  return () => { s ^= s << 13; s ^= s >> 17; s ^= s << 5; return (s >>> 0) / 0x100000000; };
}
function getDailyQuests(allQuests, counts = { facile: 3, medio: 3, difficile: 2 }, extraSeed = 0) {
  const today = new Date().toLocaleDateString('en-CA');
  const rng = _makeRng(_dateToSeed(today + "_" + extraSeed));
  const shuffle = arr => {
    const a = [...arr];
    for (let i = a.length - 1; i > 0; i--) {
      const j = Math.floor(rng() * (i + 1));
      [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
  };
  const byDiff = { facile: [], medio: [], difficile: [], epica: [] };
  for (const q of allQuests) {
    if (!q.active) continue;
    const d = normalizeMissionDifficulty(q.difficulty);
    if (byDiff[d]) byDiff[d].push(q);
  }
  return [
    ...shuffle(byDiff.facile).slice(0, counts.facile),
    ...shuffle(byDiff.medio).slice(0, counts.medio),
    ...shuffle([...byDiff.difficile, ...byDiff.epica]).slice(0, counts.difficile),
  ];
}
function hoursUntilMidnight() {
  const now = new Date();
  const midnight = new Date(now); midnight.setHours(24, 0, 0, 0);
  const ms = midnight - now;
  const h = Math.floor(ms / 3600000);
  const m = Math.floor((ms % 3600000) / 60000);
  return h > 0 ? `${h}h ${m}m` : `${m}m`;
}

function appendDiary(diary, entry) {
  const e = { ts: Date.now(), date: new Date().toLocaleDateString('it-IT', { day:'2-digit', month:'long', year:'numeric' }), ...entry };
  return [...(diary || []), e].slice(-60);
}

/* ----------------------------------------------
   LOCAL STORAGE HELPERS (per quests/monsters/meta)
---------------------------------------------- */
function lsGet(key, def) { try { const r=localStorage.getItem(key); return r?JSON.parse(r):def; } catch { return def; } }
function lsSet(key, val) { try { localStorage.setItem(key, JSON.stringify(val)); } catch { /* ignore */ } }
function slugifyAssetName(value) {
  return String(value || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

function monsterAssetPath(monster) {
  if(!monster) return "";
  return `/assets/monsters/${monster.id}-${slugifyAssetName(monster.name)}.png`;
}

