  const baseHp = monster?.maxHp || monster?.max_hp || monster?.hp || 10;
  const hpMult = (1 + (level - 1) * 0.18) * diffMult * bossMult;
  const maxHp = Math.max(1, Math.round(baseHp * hpMult));
