  const atk = Math.max(1, Math.round((monster?.atk || 5) + (level * 0.8 * diffMult) + (monster?.isBoss ? level * 0.4 : 0)));
  const def = Math.max(0, Math.round((monster?.def || 0) + (level * 0.25 * diffMult) + (monster?.isBoss ? level * 0.12 : 0)));
