  if(item.bonus_atk) lines.push(`Attacco +${item.bonus_atk}`);
  if(item.bonus_def) lines.push(`Difesa +${item.bonus_def}`);
  if(item.bonus_mag) lines.push(`Magia +${item.bonus_mag}`);
