  const attack = stats.find(s => String(s).includes("⚔️"));
  const defense = stats.find(s => String(s).includes("🛡️"));
  const heal = stats.find(s => String(s).includes("Cura"));
  const magic = stats.find(s => String(s).includes("✨"));
