  normal:    MANNEQUIN_HEAD_FRAME.human,
  slender:   MANNEQUIN_HEAD_FRAME.elf,
  stocky:    MANNEQUIN_HEAD_FRAME.dwarf,
  small:     MANNEQUIN_HEAD_FRAME.gnome,
